@startuml

class Aircraft {
  + name : string
  + type : string
  + yearOfManufacture : int
  + nextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + seatCount : int
}

class SeatCategory {
  + designation : string
  + offersEntertainment : boolean
  + seatCount : int
}

class Flight {
  + flightNumber : string
  + date : date
}

class Passenger {
  + name : string
  + passportNumber : string
}

class Ticket {
  + ticketNumber : string
  + price : float
  + upgradeDesired : boolean
}

class Airline {
  + name : string
}

class FlightAttendant {
  + name : string
  + employmentDate : date
  + isChiefStewardess : boolean
}

class Pilot {
  + name : string
  + employmentDate : date
  + license : string
}

class Airport {
  + name : string
  + address : string
  + runwayCount : int
}

Aircraft "0..*" -- "1" Airline : belongs to
PassengerAircraft "1" *-- "1..*" SeatCategory : has
Flight "0..*" -- "1" Aircraft : uses
Flight "0..*" -- "1" Airport : departs from
Flight "0..*" -- "1" Airport : arrives at
Flight "1" -- "*" Ticket : has
Passenger "1" -- "*" Ticket : holds
Ticket "*" -- "1" SeatCategory : for

Flight "0..*" -- "1..*" FlightAttendant : works on
Flight "1" -- "1" Pilot : Captain
Flight "1" -- "1..2" Pilot : Co-pilot

Aircraft "0..1" -- "1" Airport : home airport

@enduml

